// Inbound event shape:
// { source_vertical: 'sole_tax' | 'form_law' | 'manual', customer_email, customer_legal_name,
//   rolling_12m_taxable_turnover, projected_30d_turnover, currency, source_ledger_id }
const body = $json.body || {};
const THRESHOLD = 90000;
const headroom = THRESHOLD - (parseFloat(body.rolling_12m_taxable_turnover) || 0);
const forecast_breach_days = body.projected_30d_turnover && parseFloat(body.projected_30d_turnover) > 0
  ? Math.ceil(headroom / (parseFloat(body.projected_30d_turnover) / 30))
  : null;
return [{ json: {
  event_id: 'VAT-TB-' + Date.now(),
  source_vertical: body.source_vertical || 'manual',
  customer_email: body.customer_email,
  customer_legal_name: body.customer_legal_name,
  rolling_12m: parseFloat(body.rolling_12m_taxable_turnover) || 0,
  projected_30d: parseFloat(body.projected_30d_turnover) || 0,
  threshold: THRESHOLD,
  headroom_gbp: headroom,
  forecast_breach_days,
  urgency: headroom <= 5000 ? 'critical' : headroom <= 15000 ? 'high' : 'normal',
  source_ledger_id: body.source_ledger_id || null
} }];
